1	import { randomBytes } from 'node:crypto';
2	import * as vscode from 'vscode';
3	import { brainDetails } from '../../core/brain';
4	import { BRAIN_PAGE_COMMANDS, brainPageHtml, type BrainPageSection } from '../../core/brainPage';
5	import { relativeTime } from '../../core/format';
6	import type { BrainService } from '../brainService';
7	import type { RepoManager } from '../repoManager';
8	
9	export const BRAIN_VIEW_ID = 'entire.brain';
10	
11	/**
12	 * The Brain view: what the entire-brain plugin reports about the brain of
13	 * the repository, and a button that opens the brain's graph in the browser.
14	 *
15	 * It is a page and not a tree. Every row of a tree looks clickable, and the
16	 * brain's details have nothing to click: they are text. Only the buttons act.
17	 *
18	 * The page has no script. Its buttons are links to commands, and the editor
19	 * runs only the commands listed for it. The view starts collapsed, and the
20	 * editor builds the page only when it is first opened, which is when the
21	 * brain is first read.
22	 */
23	export class BrainView implements vscode.WebviewViewProvider, vscode.Disposable {
24	  private view: vscode.WebviewView | undefined;
25	  private readonly nonce = randomBytes(16).toString('base64');
26	  private readonly subscriptions: vscode.Disposable[];
27	  private readonly shown = new vscode.EventEmitter<void>();
28	  /** Fires each time the view comes on screen. */
29	  readonly onDidShow = this.shown.event;
30	  /** The page as last drawn, for the extension-host tests. */
31	  html = '';
32	
33	  constructor(
34	    private readonly manager: RepoManager,
35	    private readonly brain: BrainService,
36	  ) {
37	    const redraw = (): void => this.render();
38	    this.subscriptions = [manager.onDidChange(redraw), brain.onDidChange(redraw)];
39	  }
40	
41	  dispose(): void {
42	    for (const subscription of this.subscriptions) subscription.dispose();
43	    this.shown.dispose();
44	  }
45	
46	  /** Whether the view is open and on screen. */
47	  get visible(): boolean {
48	    return this.view?.visible === true;
49	  }
50	
51	  resolveWebviewView(view: vscode.WebviewView): void {
52	    this.view = view;
53	    view.webview.options = { enableScripts: false, enableCommandUris: BRAIN_PAGE_COMMANDS, localResourceRoots: [] };
54	    view.onDidChangeVisibility(() => {
55	      if (!view.visible) return;
56	      this.shown.fire();
57	      this.render();
58	    });
59	    view.onDidDispose(() => {
60	      if (this.view === view) this.view = undefined;
61	    });
62	    this.html = '';
63	    this.shown.fire();
64	    this.render();
65	  }
66	
67	  /** What the page shows: one section for each repository that has Entire enabled. */
68	  sections(): BrainPageSection[] {
69	    if (this.manager.viewState !== 'ready') return [];
70	    return this.manager.enabledRepos.map((repo): BrainPageSection => {
71	      const state = this.brain.stateOf(repo.root);
72	      const status = this.brain.details(repo.root)?.status;
73	      const url = this.brain.url(repo.root);
74	      return {
75	        root: repo.root,
76	        name: repo.name,
77	        state,
78	        details: state === 'ready' && status ? brainDetails(status, relativeTime(status.generatedAt)) : [],
79	        ...(url ? { running: url.replace(/^http:\/\//, '') } : {}),
80	      };
81	    });
82	  }
83	
84	  private render(): void {
85	    // Until the view has been opened there is no page to draw.
86	    if (!this.view) return;
87	    const html = brainPageHtml(this.sections(), this.nonce);
88	    // Setting the page reloads it, so it is set only when it has changed.
89	    if (html === this.html) return;
90	    this.html = html;
