41	
42	/** A filter as one string: `all`, `open`, `closed`, or `open:<phase>`. */
43	export function trailFilterKey(filter: TrailFilter): string {
44	  return filter.phase ? `${filter.status}:${filter.phase}` : filter.status;
45	}
