48	export function readTrailFilter(key: unknown): TrailFilter | undefined {
49	  if (typeof key !== 'string') return undefined;
50	  if (key === 'all' || key === 'open' || key === 'closed') return { status: key };
51	  const [status, phase, ...rest] = key.split(':');
52	  // Only an open trail has a phase to tell apart. A closed one is in the closed phase.
53	  if (status !== 'open' || !phase || rest.length > 0 || !PHASE_NAME.test(phase)) return undefined;
54	  return { status: 'open', phase };
