1	const MINUTE = 60_000;
2	const HOUR = 60 * MINUTE;
3	const DAY = 24 * HOUR;
4	
5	/** "5m ago", "3h ago", "6d ago", then a date. Empty for an unknown time. */
6	export function relativeTime(time: number | string | undefined, now = Date.now()): string {
7	  if (time === undefined || time === '') return '';
8	  const then = typeof time === 'number' ? time : Date.parse(time);
9	  if (!Number.isFinite(then)) return '';
10	  const elapsed = now - then;
11	  if (elapsed < MINUTE) return 'just now';
12	  if (elapsed < HOUR) return `${Math.floor(elapsed / MINUTE)}m ago`;
13	  if (elapsed < DAY) return `${Math.floor(elapsed / HOUR)}h ago`;
14	  if (elapsed < 30 * DAY) return `${Math.floor(elapsed / DAY)}d ago`;
15	  const date = new Date(then);
16	  const sameYear = date.getFullYear() === new Date(now).getFullYear();
17	  return (sameYear ? DAY_OF_YEAR : DAY_WITH_YEAR).format(date);
18	}
19	
20	// Made once: building a formatter costs far more than using one, and a list
21	// formats a date for every row each time it redraws.
22	const DAY_OF_YEAR = new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric' });
23	const DAY_WITH_YEAR = new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
24	
25	/** 950 -> "950", 12_400 -> "12.4K", 10_407_798 -> "10.4M". */
26	export function formatTokens(count: number): string {
27	  if (count < 1000) return String(count);
28	  let value = count;
29	  let unit = '';
30	  for (const next of ['K', 'M', 'B']) {
31	    value /= 1000;
32	    unit = next;
33	    // Rounding can reach 1000 (999,950 would read "1000K"), which belongs to the next unit.
34	    if (Number(value.toFixed(1)) < 1000) break;
35	  }
36	  return `${trimZero(value.toFixed(1))}${unit}`;
37	}
38	
39	/**
40	 * "12 of 249" for a checkpoint's place in its session. A plus sign after the
41	 * total means the session may have earlier checkpoints than the ones counted.
42	 */
43	export function formatPosition(position: { ordinal: number; total: number; mayHaveEarlier: boolean }): string {
44	  const total = `${position.total.toLocaleString('en-US')}${position.mayHaveEarlier ? '+' : ''}`;
45	  return `${position.ordinal.toLocaleString('en-US')} of ${total}`;
46	}
47	
48	/** Shortens text to `limit` characters, ending in an ellipsis, without splitting a surrogate pair. */
49	export function truncate(text: string, limit: number): string {
50	  if (text.length <= limit) return text;
51	  let end = Math.max(0, limit - 1);
52	  const edge = text.charCodeAt(end - 1);
53	  if (edge >= 0xd800 && edge <= 0xdbff) end -= 1;
54	  return `${text.slice(0, end)}…`;
55	}
56	
57	function trimZero(value: string): string {
58	  return value.endsWith('.0') ? value.slice(0, -2) : value;
59	}
60	
61	/** The first non-empty line of `text`, shortened to `limit` characters. */
62	export function headline(text: string | undefined, limit = 90): string {
63	  if (!text) return '';
64	  const line = text
65	    .split('\n')
66	    .map((candidate) => candidate.trim())
67	    .find((candidate) => candidate !== '');
68	  if (!line) return '';
69	  return truncate(line, limit);
70	}
71	
72	/** Joins the parts that have content with a middle dot. */
73	export function joinParts(...parts: (string | undefined)[]): string {
74	  return parts.filter((part): part is string => !!part).join(' · ');
75	}
