12	const NO_WEB =
13	  'Links to entire.com are available when the origin remote uses the entire:// scheme.';
14	
15	/** User-facing operations shared by the tree views and the detail panel. */
16	export class Actions {
17	  constructor(
18	    private readonly manager: RepoManager,
19	    private readonly text: TextProvider,
20	    private readonly transcripts: TranscriptFiles,
21	  ) {}
22	
23	  async openRepoOnWeb(repo: RepoContext): Promise<void> {
24	    if (!repo.entireRepo) return void vscode.window.showInformationMessage(NO_WEB);
25	    await this.openExternal(repoUrl(this.manager.webBase(), repo.entireRepo));
26	  }
27	
28	  /** Opens the commit page, which is where entire.com shows a commit's checkpoint. */
29	  async openCommitOnWeb(repo: RepoContext, sha: string): Promise<void> {
30	    if (!repo.entireRepo) return void vscode.window.showInformationMessage(NO_WEB);
31	    if (!(await this.manager.git.isOnRemote(repo.root, sha))) {
32	      const choice = await vscode.window.showWarningMessage(
33	        'This commit is not on a remote yet, so entire.com may not have it.',
34	        'Open Anyway',
35	      );
36	      if (choice !== 'Open Anyway') return;
37	    }
