46	  /** Opens a trail's page. The address comes from the CLI, which may have to look it up first. */
47	  async openTrailOnWeb(repo: RepoContext, trail: number): Promise<void> {
48	    const url = await this.trailUrl(repo, trail);
49	    if (url) await this.openExternal(url);
50	  }
51	
52	  async copyTrailLink(repo: RepoContext, trail: number): Promise<void> {
53	    const url = await this.trailUrl(repo, trail);
54	    if (url) await this.copy(url, 'trail link');
55	  }
56	
57	  private async trailUrl(repo: RepoContext, trail: number): Promise<string | undefined> {
58	    if (!repo.entireRepo) return void vscode.window.showInformationMessage(NO_WEB);
59	    const url = await vscode.window.withProgress(
60	      { location: vscode.ProgressLocation.Window, title: 'Entire: looking up the trail' },
61	      () => this.manager.trailUrl(repo, trail),
62	    );
63	    if (!url) void vscode.window.showErrorMessage('Entire could not look up the web page of this trail.');
64	    return url;
65	  }
