68	  async openExternal(href: string): Promise<void> {
69	    let url: URL;
70	    try {
71	      url = new URL(href);
72	    } catch {
73	      return;
74	    }
75	    if (url.protocol !== 'https:' && url.protocol !== 'http:') return;
