183	  ): Promise<void> {
184	    const [left, right] = this.sides(repo, sha, parent, file);
185	    await vscode.commands.executeCommand(
186	      'vscode.diff',
187	      left,
188	      right,
189	      `${path.basename(file.path)} (${sha.slice(0, 8)})`,
190	      { preview: true },
191	    );
192	  }
193	
194	  private async showDocument(uri: vscode.Uri): Promise<void> {
195	    try {
196	      const document = await vscode.workspace.openTextDocument(uri);
197	      await vscode.window.showTextDocument(document, { preview: true });
198	    } catch (error) {
199	      void vscode.window.showErrorMessage(error instanceof Error ? error.message : 'Entire could not open that document.');
200	    }
201	  }
202	}
