  }
  const fields = [
    trail.title,
    trail.body,
    trail.status,
    trail.phase,
    trail.type,
    ...trail.changes.flatMap((change) => [change.branch, change.title, change.repository]),
  ];
  const haystack = fields
    .filter((field): field is string => !!field)
    .join('\n')
    .toLowerCase();
  return words.every((word) => haystack.includes(word));
}

