    case 'posix':
      return /^[A-Za-z0-9_./+-]+$/.test(program) ? program : `'${program.replace(/'/g, `'\\''`)}'`;
    case 'powershell':
      return `& '${program.replace(/'/g, "''")}'`;
    case 'cmd':
      // A Windows path cannot hold a double quote, so this cannot be closed early.
      return `"${program.replace(/"/g, '')}"`;
  }
