  const line = (view: SetupStepView): string =>
    `${view.id}: ${view.state}${view.buttons.length > 0 ? ` [${view.buttons.map((button) => button.action).join(', ')}]` : ''}`;
  return [...model.machine.map(line), ...model.repos.flatMap((entry) => entry.steps.map(line))];
