describe('setupModel', () => {
  it('says everything is done for a repository that is fully set up', () => {
    const model = setupModel(machine(), [repo()]);
    expect(summary(model)).toEqual([
      'cli: done',
      'login: done',
      'enable: done',
      'graph: done',
      'brain: done',
      'connect: done',
