import * as vscode from 'vscode';
import { hasBrain, type BrainStatus } from '../core/brain';
import { fail, type Failure } from '../core/errors';
import type { RunningServer } from '../core/serverProcess';
import type { RepoContext, RepoManager } from './repoManager';

/** How a request to open the brain graph ended. The caller words the message. */
export type BrainOutcome =
  /** The page is open. `started` says whether a server had to be started for it. */
  | { kind: 'opened'; url: string; started: boolean }
  /** The entire-brain plugin is not installed. */
  | { kind: 'pluginMissing' }
  /** The repository has no brain yet. */
  | { kind: 'noBrain' }
  | { kind: 'cancelled' }
  | { kind: 'failed'; message: string };

/** What the Brain view shows: the brain's details, or the reason it has none. */
export type BrainViewState = 'loading' | 'pluginMissing' | 'noBrain' | 'failed' | 'ready';

/** What is known about the brain of one repository, as far as it has been read. */
export interface BrainInfo {
  loading: boolean;
  /** The plugin's last report. Kept while a fresh one is read. */
  status?: BrainStatus;
  /** Why the last read gave no report. */
  failure?: Failure;
}

interface Running {
  server: RunningServer;
  /** The branch that was checked out when the server started. It reads the branch once. */
  branch: string | undefined;
}

/**
 * The brain of each open repository: what the entire-brain plugin reports
 * about it, for the Brain view, and the plugin's graph page.
 *
 * The report is read when the Brain view is first shown and on Refresh, and
 * not before: the view starts collapsed, and a repository may have no brain.
 *
 * The graph page is the one `entire brain viz` serves on the loopback
 * address. It opens in the browser. It cannot be shown in an editor tab,
 * because the plugin's server forbids every other page from framing it
 * (`frame-ancestors 'none'`). The server runs until it is stopped, so this
 * owns one per repository and stops them all when the window closes.
 *
 * Nothing here installs the plugin or builds a brain. Both write, so they
 * run as Setup steps, in a terminal, when the user asks (see SetupService).
 */
export class BrainService implements vscode.Disposable {
  /**
   * Opens a page of a server on this machine. The address goes through
   * `asExternalUri` first, which forwards the port when the extension runs
   * on another machine than the browser. The extension-host tests replace
   * this, so that no browser opens.
   */
  openUrl: (url: string) => Thenable<unknown> = async (url) =>
    vscode.env.openExternal(await vscode.env.asExternalUri(vscode.Uri.parse(url, true)));

  private readonly info = new Map<string, BrainInfo>();
  /** Counts the reads of each repository's report, so a late answer to an earlier one is dropped. */
  private readonly reads = new Map<string, number>();
  private readonly servers = new Map<string, Running>();
  /** Starts under way, by repository, so that two requests share one. */
  private readonly starting = new Map<string, Promise<BrainOutcome>>();
  private readonly changed = new vscode.EventEmitter<void>();
  /** Fires when a report arrives or a server starts or stops. */
  readonly onDidChange = this.changed.event;
  private readonly subscription: vscode.Disposable;
  private disposed = false;

  constructor(
    private readonly manager: RepoManager,
    private readonly log: vscode.LogOutputChannel,
  ) {
    // A repository that leaves the window takes its report and its server with it.
    this.subscription = manager.onDidChange(() => {
      let dropped = false;
      for (const root of new Set([...this.servers.keys(), ...this.info.keys()])) {
        if (manager.repoFor(root)) continue;
        this.servers.get(root)?.server.stop();
        this.servers.delete(root);
        this.info.delete(root);
        dropped = true;
      }
      // The state the view shows also depends on which repositories have Entire enabled.
      this.sync();
      if (dropped) this.changed.fire();
    });
    this.sync();
  }

  /** What has been read about the brain of a repository. Undefined until the Brain view asks. */
  details(root: string): BrainInfo | undefined {
    return this.info.get(root);
  }

  /**
   * What the Brain view shows. With one repository, a brain that cannot be
   * listed leaves the view empty and this says why. With several, each
   * repository has a row of its own and says so under it.
   */
  state(): BrainViewState {
    const repos = this.manager.enabledRepos;
    if (repos.length !== 1 || !repos[0]) return 'ready';
    return this.stateOf(repos[0].root);
  }

  /** The same, for one repository. */
  stateOf(root: string): BrainViewState {
    const info = this.info.get(root);
    if (!info || (info.loading && !info.status && !info.failure)) return 'loading';
    if (info.status) return hasBrain(info.status) ? 'ready' : 'noBrain';
    return info.failure?.kind === 'pluginMissing' ? 'pluginMissing' : 'failed';
  }

  /**
   * Reads the report of each repository that has not been asked about yet.
   * The Brain view calls this when it is shown.
   */
  ensureStatus(): void {
    for (const repo of this.manager.enabledRepos) {
      if (!this.info.has(repo.root)) void this.loadStatus(repo);
    }
  }

  /** Reads again every report that has been read. Refresh calls this. */
  refresh(): void {
    for (const root of [...this.info.keys()]) {
      const repo = this.manager.repoFor(root);
      if (repo) void this.loadStatus(repo);
    }
  }

  /** Reads the plugin's report on one repository. The one already shown stays until the answer arrives. */
  async loadStatus(repo: RepoContext, signal?: AbortSignal): Promise<BrainInfo> {
    const cli = this.manager.cli;
    const read = (this.reads.get(repo.root) ?? 0) + 1;
    this.reads.set(repo.root, read);
    const before = this.info.get(repo.root);
    const pending: BrainInfo = { ...before, loading: true };
    this.info.set(repo.root, pending);
    this.announce();

    const result = cli
      ? await cli.brainStatus(repo.root, signal)
      : fail<BrainStatus>('cliMissing', 'The Entire CLI is not available.');
    // A newer read, or the repository leaving the window, makes this answer stale.
    if (this.reads.get(repo.root) !== read || this.info.get(repo.root) !== pending) {
      return this.info.get(repo.root) ?? { loading: false };
    }
    if (!result.ok && result.failure.kind === 'aborted') {
      // A cancelled read says nothing new. What was known before still stands.
      if (before) this.info.set(repo.root, { ...before, loading: false });
      else this.info.delete(repo.root);
      this.announce();
      return this.info.get(repo.root) ?? { loading: false, failure: result.failure };
    }
    const next: BrainInfo = result.ok ? { loading: false, status: result.value } : { loading: false, failure: result.failure };
    if (!result.ok && result.failure.kind !== 'pluginMissing') {
      this.log.warn(`${repo.name}: ${result.failure.message} ${result.failure.detail ?? ''}`.trim());
    }
    this.info.set(repo.root, next);
    this.announce();
    return next;
  }

  /** Whether a graph server is up, for one repository or for any. */
  running(root?: string): boolean {
    return root === undefined ? this.servers.size > 0 : this.servers.has(root);
  }

  /** The address of the repository's graph page, while its server runs. */
  url(root: string): string | undefined {
    return this.servers.get(root)?.server.url;
  }

  /** Whether opening the graph has to start a server first, which takes a moment. */
  needsStart(repo: RepoContext): boolean {
    const running = this.servers.get(repo.root);
    return !running || running.branch !== repo.branch;
  }

  /**
   * Opens the graph of a repository's brain, starting its server when none
   * runs. `signal` gives up on a start that is still under way.
   */
  async open(repo: RepoContext, signal?: AbortSignal): Promise<BrainOutcome> {
    if (this.disposed) return { kind: 'cancelled' };
    const running = this.servers.get(repo.root);
    if (running && running.branch === repo.branch) {
      await this.openUrl(running.server.url);
      return { kind: 'opened', url: running.server.url, started: false };
    }
    // The server read the branch when it started. Another branch needs another server.
    if (running) this.stop(repo.root);

    let start = this.starting.get(repo.root);
    if (!start) {
      start = this.start(repo, signal).finally(() => this.starting.delete(repo.root));
      this.starting.set(repo.root, start);
    }
    return start;
  }

  private async start(repo: RepoContext, signal?: AbortSignal): Promise<BrainOutcome> {
    const cli = this.manager.cli;
    if (!cli) return { kind: 'failed', message: 'The Entire CLI is not available.' };

    // The server would start without a brain and show an empty page, so the report is read first.
    const info = await this.loadStatus(repo, signal);
    if (signal?.aborted) return { kind: 'cancelled' };
    if (info.status) {
      if (!hasBrain(info.status)) return { kind: 'noBrain' };
    } else if (info.failure?.kind === 'pluginMissing') {
      return { kind: 'pluginMissing' };
    }
    // Any other failure to read the report is no reason not to try: the page says what the brain holds.

    const started = await cli.startBrainViz(repo.root, signal);
    if (!started.ok) {
      if (started.failure.kind === 'pluginMissing') return { kind: 'pluginMissing' };
      if (started.failure.kind === 'aborted') return { kind: 'cancelled' };
      this.log.warn(`${repo.name}: ${started.failure.message} ${started.failure.detail ?? ''}`.trim());
      return { kind: 'failed', message: started.failure.message };
    }
    const server = started.value;
    if (this.disposed || !this.manager.repoFor(repo.root)) {
      // The window closed, or the repository left it, while the server started.
      server.stop();
      return { kind: 'cancelled' };
    }
    this.servers.set(repo.root, { server, branch: repo.branch });
    void server.exited.then(() => {
      if (this.servers.get(repo.root)?.server !== server) return;
      this.servers.delete(repo.root);
      this.announce();
    });
    this.announce();
    await this.openUrl(server.url);
    return { kind: 'opened', url: server.url, started: true };
  }

  /** Stops the graph server of one repository, or every server. */
  stop(root?: string): void {
    for (const key of root === undefined ? [...this.servers.keys()] : [root]) {
      this.servers.get(key)?.server.stop();
      this.servers.delete(key);
    }
    this.announce();
  }

  dispose(): void {
    this.disposed = true;
    this.subscription.dispose();
    this.stop();
    this.changed.dispose();
  }

  /** Publishes what the Brain view and the Stop command depend on, then redraws the view. */
  private announce(): void {
    this.sync();
    if (!this.disposed) this.changed.fire();
  }

  private sync(): void {
    void vscode.commands.executeCommand('setContext', 'entire.brainRunning', this.servers.size > 0);
    void vscode.commands.executeCommand('setContext', 'entire.brainState', this.state());
  }
}

// Runs inside a VS Code extension host, in a window of its own: a repository
// on Entire where nothing is set up yet. See .vscode-test.mjs. The tests
// replace the runner that types each step's command into a terminal, so that
// nothing is installed, enabled, or logged into for real. Each stand-in run
// changes what the fake Entire CLI replies, as the real command would.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vscode = require('vscode');

const fixture = JSON.parse(fs.readFileSync(process.env.ENTIRE_TEST_FIXTURE, 'utf8'));

/** Every fake CLI invocation so far, as "arg arg arg" strings. */
function invocations() {
  return fs
    .readFileSync(fixture.logFile, 'utf8')
    .split('\n')
    .filter(Boolean)
    .map((line) => JSON.parse(line).join(' '));
}
const calls = (prefix) => invocations().filter((call) => call.startsWith(prefix));

async function until(check, label, timeoutMs = 30_000) {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    const value = await check();
    if (value) return value;
    if (Date.now() > deadline) throw new Error(`Timed out waiting for ${label}`);
    await new Promise((resolve) => setTimeout(resolve, 50));
  }
}

const json = (value) => ({ stdout: JSON.stringify(value) });

suite('Entire setup', () => {
  /** @type {import('../../src/extension').EntireTestApi} */
  let api;
  let manifest;
  /** What the fake CLI replies on top of the scenario, as the steps run. */
  let replies = {};
  /** Changes what the fake CLI replies from now on. */
  const reply = (changes) => {
    replies = { ...replies, ...changes };
    fs.writeFileSync(fixture.scenarioFile, JSON.stringify({ ...fixture.scenario, ...replies }));
  };
  /** The commands the stand-in runner was given. */
  const runs = [];
  /** What each stand-in run does, by the end of its command line. */
  let effects = {};
  let tracked = true;

  /** The steps of the page as "id: state [actions]". */
  const steps = () => {
    const page = api.setup.page();
    assert.equal(page.kind, 'steps');
    const line = (view) => `${view.id}: ${view.state}${view.buttons.length ? ` [${view.buttons.map((button) => button.action).join(', ')}]` : ''}`;
    return [...page.model.machine.map(line), ...page.model.repos.flatMap((entry) => entry.steps.map(line))];
  };
  const settled = () => steps().every((line) => !line.includes(': checking'));
  const run = (root, action) => vscode.commands.executeCommand('entire.runSetupStep', root, action);

  suiteSetup(async () => {
    const extension = vscode.extensions.getExtension('entire.entire');
    assert.ok(extension, 'the extension is installed in the test host');
    manifest = extension.packageJSON.contributes;
    api = await extension.activate();
    await until(() => api.manager.viewState === 'notEnabled', 'the first load');
  });

  suiteTeardown(() => {
    replies = {};
    reply({});
  });

  test('is first in the sidebar, and shows itself while Entire is not enabled', async () => {
    assert.deepEqual(manifest.views.entire[0], { id: 'entire.setup', name: 'Setup', type: 'webview', when: 'entire.showSetup' });
    assert.equal(api.setup.showSetup, true);
    assert.equal(api.setup.pinned, false);
    // The welcome text of the other views leads here.
    const welcome = manifest.viewsWelcome.filter((entry) => /cliMissing|cliTooOld|notEnabled/.test(entry.when));
    assert.equal(welcome.length, 6);
    for (const entry of welcome) assert.match(entry.contents, /\[Set Up Entire\]\(command:entire\.openSetup\)/);
    // Nothing is read for it until it is on screen. Someone watching this window may have opened it already.
    if (!api.setupView.visible) {
      assert.equal(api.setupView.html, '');
      assert.deepEqual(calls('auth'), []);
      assert.deepEqual(calls('graph'), []);
    }
  });

  test('opens a terminal named for setup, and runs a command line in it', async () => {
    const result = await api.setup.runner.run({ cwd: fixture.root, terminalName: 'Entire Setup', commandLine: 'echo entire-setup-test' });
    assert.equal(typeof result.tracked, 'boolean');
    if (result.tracked && result.exitCode !== undefined) assert.equal(result.exitCode, 0);
    assert.ok(vscode.window.terminals.some((terminal) => terminal.name === 'Entire Setup'));
    for (const terminal of vscode.window.terminals) terminal.dispose();
  });

  test('reads every step when it is opened, and stays from then on', async () => {
    // From here on, a stand-in runs the commands.
    api.setup.runner = {
      run: async (request) => {
        runs.push(request);
        const effect = Object.entries(effects).find(([ending]) => request.commandLine.endsWith(ending));
        if (effect) await effect[1](request);
        return tracked ? { tracked: true, exitCode: 0 } : { tracked: false };
      },
    };
    await vscode.commands.executeCommand('entire.openSetup');
    await until(() => api.setupView.visible, 'the Setup view to show');
    assert.equal(api.setup.pinned, true);
    await until(settled, 'every step to be read');
    assert.deepEqual(steps(), [
      'cli: done',
      // The repository is on Entire, so the login is needed for its trails and its hosted brain.
      'login: needed [login]',
      'enable: needed [enable]',
      'graph: optional [installGraph]',
      'brain: optional [setupBrain]',
      'connect: blocked',
    ]);
    assert.ok(calls('auth status --json').length >= 1);
    assert.ok(calls('graph version --json').length >= 1);
    assert.ok(calls('brain status --json').length >= 1);
    assert.match(api.setupView.html, /Brain Connect/);
    assert.doesNotMatch(api.setupView.html, /<script/i);
  });

  test('runs nothing for a step it does not know, or for a repository that is not open', async () => {
    await run(fixture.root, 'rm -rf');
    await run('/no/such/repository', 'enable');
    await run(undefined, 'enable');
    assert.equal(runs.length, 0);
  });

  test('enables Entire in a terminal, and shows the views when the command ends, without a refresh', async () => {
    effects = { ' enable': () => reply({ 'status --json': fixture.enabledStatus }) };
    await run(fixture.root, 'enable');
    assert.equal(runs.length, 1);
    assert.equal(runs[0].cwd, fixture.root);
    assert.equal(runs[0].terminalName, 'Entire Setup');
    // The CLI, as the setting names it, then constant arguments.
    assert.equal(runs[0].commandLine, `${fixture.cli} enable`);
    await until(() => api.manager.viewState === 'ready', 'Entire to be enabled');
    // The view stays for the steps that are left.
    assert.equal(api.setup.showSetup, true);
    await until(() => steps().includes('enable: done'), 'the step to be done');
  });

  test('logs in, and reads again what a login changes', async () => {
    effects = { ' login': () => reply({ 'auth status --json': json({ logged_in: true, user: 'github:fixture-author' }) }) };
    const reloads = calls('status --json').length;
    await run(null, 'login');
    assert.match(runs.at(-1).commandLine, / login$/);
    await until(() => steps().includes('login: done'), 'the login to be done');
    // A login is followed by a refresh, which reads the status again.
    assert.ok(calls('status --json').length > reloads);
  });

  test('installs the Graph plugin, then sets it up', async () => {
    effects = { ' plugin install graph': () => reply({ 'graph version --json': json({ version: 'v0.6.0' }) }) };
    await run(fixture.root, 'installGraph');
    assert.match(runs.at(-1).commandLine, / plugin install graph$/);
    await until(() => steps().includes('graph: optional [setupGraph]'), 'the plugin to be installed');

    effects = {
      ' graph setup': () => {
        fs.mkdirSync(path.join(fixture.root, '.entire'), { recursive: true });
        fs.writeFileSync(path.join(fixture.root, '.entire', 'agent-guide.md'), 'Run entire graph query before you edit.\n');
      },
    };
    await run(fixture.root, 'setupGraph');
    await until(() => steps().includes('graph: done'), 'Graph to be set up');
  });

  test('counts a command it cannot follow as running until the user checks', async () => {
    tracked = false;
    effects = {};
    await run(fixture.root, 'setupBrain');
    assert.match(runs.at(-1).commandLine, / brain setup$/);
    assert.ok(steps().includes('brain: running'));
    assert.match(api.setupView.html, /Running in the terminal/);

    reply({ 'brain status --json': json({ brain: { manifest_state: 'current' }, hosted: { state: 'disconnected' } }) });
    await vscode.commands.executeCommand('entire.checkSetup');
    await until(() => steps().includes('brain: done'), 'the brain to be built');
    tracked = true;
    // With a brain and a login, the brain can connect to its hosted brain.
    assert.ok(steps().includes('connect: optional [connectBrain]'));
  });

  test('connects the brain, and then everything is set up', async () => {
    effects = {
      ' brain connect': () =>
        reply({ 'brain status --json': json({ brain: { manifest_state: 'current' }, hosted: { state: 'connected', synced: true } }) }),
    };
    await run(fixture.root, 'connectBrain');
    await until(() => steps().includes('connect: done'), 'the brain to connect');
    assert.equal(api.setup.page().model.complete, true);
    assert.match(api.setupView.html, /Entire is set up\./);
  });

  test('leaves the sidebar when hidden, and comes back when asked', async () => {
    await vscode.commands.executeCommand('entire.hideSetup');
    assert.equal(api.setup.pinned, false);
    assert.equal(api.setup.showSetup, false);
    await vscode.commands.executeCommand('entire.openSetup');
    assert.equal(api.setup.showSetup, true);
    await vscode.commands.executeCommand('entire.hideSetup');
  });

  test('copies nothing and runs every command through the runner', () => {
    // Every setup command went to the stand-in. None ran as a child of the extension.
    assert.deepEqual(calls('enable'), []);
    assert.deepEqual(calls('login'), []);
    assert.deepEqual(calls('plugin'), []);
    assert.deepEqual(calls('graph setup'), []);
    assert.deepEqual(calls('brain setup'), []);
    assert.deepEqual(calls('brain connect'), []);
  });
});

// Runs inside a VS Code extension host, last in the window that extension.test.cjs,
// trails.test.cjs, and brain.test.cjs share. See .vscode-test.mjs for what the
// fake Entire CLI's search answers. The picker itself is a widget the tests
// cannot type into, so they drive the search through the engine behind it,
// which builds the same items, and open what it found as a pick would.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const vscode = require('vscode');

const fixture = JSON.parse(fs.readFileSync(process.env.ENTIRE_TEST_FIXTURE, 'utf8'));

/** Every fake CLI invocation so far, as "arg arg arg" strings. */
function invocations() {
  return fs
    .readFileSync(fixture.logFile, 'utf8')
    .split('\n')
    .filter(Boolean)
    .map((line) => JSON.parse(line).join(' '));
}
const calls = (prefix) => invocations().filter((call) => call.startsWith(prefix));

async function until(check, label, timeoutMs = 30_000) {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    const value = await check();
    if (value) return value;
    if (Date.now() > deadline) throw new Error(`Timed out waiting for ${label}`);
    await new Promise((resolve) => setTimeout(resolve, 50));
  }
}

const SEPARATOR = -1;

suite('Entire search', () => {
  /** @type {import('../../src/extension').EntireTestApi} */
  let api;
  let repo;
  /** Changes what the fake CLI replies from now on. */
  const reply = (changes) => fs.writeFileSync(fixture.scenarioFile, JSON.stringify({ ...fixture.scenario, ...changes }));
  /** The items as "label | description", headings as "-- label --". */
  const lines = (items) =>
    items.map((item) => (item.kind === SEPARATOR ? `-- ${item.label} --` : `${item.label} | ${item.description ?? ''}`));
  const results = (items) => items.filter((item) => item.target);

  suiteSetup(async () => {
    const extension = vscode.extensions.getExtension('entire.entire');
    assert.ok(extension, 'the extension is installed in the test host');
    api = await extension.activate();
    await until(() => api.manager.viewState === 'ready', 'the first load');
    repo = api.manager.repoFor(fixture.root);
    assert.ok(repo, 'the fixture repository is open');
    // The commits and their checkpoints, which local matching reads.
    await until(() => repo.index?.commits.length > 0 && repo.index.allRows().length > 0, 'the checkpoints to be read');
  });

  suiteTeardown(async () => {
    reply({});
    await api.setup.hide();
  });

  test('asks Entire nothing until a search is made', () => {
    assert.deepEqual(calls('search'), []);
  });

  test('has a Search button on each view, and the command in the palette', () => {
    const { menus, commands } = vscode.extensions.getExtension('entire.entire').packageJSON.contributes;
    assert.deepEqual(
      menus['view/title'].filter((entry) => entry.command.startsWith('entire.search')),
      [
        { command: 'entire.searchCheckpoints', when: "view == entire.checkpoints && entire.viewState == 'ready'", group: 'navigation@0' },
        { command: 'entire.searchSessions', when: "view == entire.sessions && entire.viewState == 'ready'", group: 'navigation@0' },
        { command: 'entire.searchTrails', when: 'view == entire.trails', group: 'navigation@0' },
      ],
    );
    for (const command of ['entire.search', 'entire.searchCheckpoints', 'entire.searchSessions', 'entire.searchTrails']) {
      assert.equal(commands.find((entry) => entry.command === command)?.icon, '$(search)', command);
    }
    // The search is always in the palette: it says what to set up when there is nothing to search.
    assert.equal(menus.commandPalette.find((entry) => entry.command === 'entire.search'), undefined);
  });

  test('matches what the views have read at once, without asking Entire', () => {
    const groups = api.search.engine().local('parser');
    assert.deepEqual(
      groups.checkpoints.map((item) => item.label),
      ['Add the parser'],
    );
    assert.deepEqual(groups.checkpoints[0].target, {
      kind: 'checkpoint',
      root: fixture.root,
      checkpointId: fixture.ids.refs,
      commitSha: fixture.parserCommit,
    });
    assert.match(groups.checkpoints[0].description, /^Checkpoint · [0-9a-f]{7,} · Claude Code · /);
    assert.deepEqual(calls('search'), []);
  });

  test('lists the newest checkpoints and sessions before anything is typed', () => {
    const groups = api.search.engine().recent();
    assert.ok(groups.checkpoints.length > 0);
    assert.ok(groups.sessions.length > 0);
    assert.deepEqual(calls('search'), []);
  });

  test("adds Entire's results, best first, under their kind, without repeating a checkpoint", async () => {
    const items = await api.search.engine().collect('parser');
    assert.equal(calls(fixture.searchKey).length, 1);
    const shown = lines(items);
    assert.deepEqual(shown.slice(0, 1), ['-- Checkpoints --']);
    // The commit Entire ranked first is the one the views have read: it is listed once, as Entire ranked it.
    assert.equal(shown.filter((line) => line.startsWith('Add the parser |')).length, 1);
    assert.match(shown[1], /^Add the parser \| Checkpoint · [0-9a-f]{7} · main · Fixture Author/);
    assert.match(shown[2], /^Write down how the parser works \| Commit · ffffffff?/);
    const sessions = shown.indexOf('-- Sessions --');
    assert.ok(sessions > 0, 'the sessions have a heading');
    assert.match(shown[sessions + 1], /^Tune the Parser Elsewhere \| Session · Codex · tune-lexer/);
    // The session's line under it is the part of its transcript that matched.
    assert.equal(results(items).find((item) => item.target.kind === 'session').detail, '[user]: Tune the parser [assistant]: It is tuned.');
    // A pull request is not something the extension can open.
    assert.ok(!shown.some((line) => line.startsWith('Parser pull request')));
    for (const item of results(items)) assert.equal(item.alwaysShow, true);
  });

  test('searches one kind when a view asks', async () => {
    const before = calls(fixture.searchKey).length;
    const items = await api.search.engine().collect('parser', 'sessions');
    assert.equal(calls(fixture.searchKey).length, before + 1);
    // One kind needs no heading.
    assert.ok(items.every((item) => item.kind !== SEPARATOR));
    assert.ok(results(items).every((item) => item.target.kind === 'session'));
    assert.ok(results(items).some((item) => item.target.sessionId === 'searched-session'));
  });

  test('finds trails by number, read once for the search', async () => {
    const engine = api.search.engine();
    const before = calls(`trail list --project gh/acme --repo gh/acme/widget --limit 50 --json`).length;
    const items = await engine.collect('#118', 'trails');
    assert.deepEqual(
      results(items).map((item) => [item.label, item.target]),
      [['Trail 118', { kind: 'trail', root: fixture.root, number: 118, id: fixture.trailIds[118] }]],
    );
    // A closed trail is found too: the search reads every trail, not only the open ones.
    const closed = await engine.collect('9002', 'trails');
    assert.deepEqual(results(closed).map((item) => item.target.number), [9002]);
    assert.equal(calls(`trail list --project gh/acme --repo gh/acme/widget --limit 50 --json`).length, before + 1);
    // Trails are never sent to Entire's search.
    assert.deepEqual(calls('search --json --limit 25 -- #118'), []);
  });

  test('opens a session that only Entire knows at the checkpoint that matched', async () => {
    const items = await api.search.engine().collect('parser', 'sessions');
    const session = results(items).find((item) => item.target.sessionId === 'searched-session');
    await api.search.accept(session, { newTab: false });
    const header = await until(() => {
      const snapshot = api.panels.current?.snapshot();
      return snapshot && 'header' in snapshot && snapshot.header.checkpointId === fixture.ids.onEntire ? snapshot.header : undefined;
    }, 'the panel to show the checkpoint that matched');
    assert.equal(header.mode, 'checkpoint');
  });

  test('opens a checkpoint it found in the detail panel', async () => {
    const items = await api.search.engine().collect('parser', 'checkpoints');
    const checkpoint = results(items).find((item) => item.target.checkpointId === fixture.ids.refs);
    await api.search.accept(checkpoint, { newTab: false });
    await until(() => {
      const snapshot = api.panels.current?.snapshot();
      return snapshot && 'header' in snapshot && snapshot.header.checkpointId === fixture.ids.refs;
    }, 'the panel to show the checkpoint');
  });

  test('offers a login when Entire says there is none, and runs it as a Setup step', async () => {
    reply({ [fixture.searchKey]: { stderr: 'Error: not logged in. Run entire login.\n', exitCode: 1 } });
    const items = await api.search.engine().collect('parser');
    const hint = items.at(-1);
    assert.equal(hint.hint, 'login');
    assert.equal(hint.label, 'Log in to Entire to search sessions and trails on Entire');
    // What the views have read is still found.
    assert.ok(results(items).some((item) => item.label === 'Add the parser'));

    const runs = [];
    api.setup.runner = {
      run: async (request) => {
        runs.push(request);
        return { tracked: true, exitCode: 0 };
      },
    };
    await api.search.accept(hint, { newTab: false });
    assert.equal(runs.length, 1);
    assert.match(runs[0].commandLine, / login$/);
    assert.equal(runs[0].terminalName, 'Entire Setup');
  });

  test('says when Entire could not be searched, and keeps what it found here', async () => {
    reply({ [fixture.searchKey]: { stderr: 'internal error\n', exitCode: 1 } });
    const items = await api.search.engine().collect('parser');
    assert.equal(items.at(-1).hint, 'log');
    assert.ok(results(items).some((item) => item.label === 'Add the parser'));
  });

  test('asks only what it has read when searching Entire is turned off', async () => {
    reply({});
    const config = vscode.workspace.getConfiguration('entire');
    await config.update('search.hosted', false, vscode.ConfigurationTarget.Global);
    try {
      const before = calls('search').length;
      const items = await api.search.engine().collect('parser', 'checkpoints');
      assert.equal(calls('search').length, before);
      assert.deepEqual(
        results(items).map((item) => item.label),
        ['Add the parser'],
      );
    } finally {
      await config.update('search.hosted', undefined, vscode.ConfigurationTarget.Global);
    }
  });
});

# Example: Electron / desktop GUI app

Electron apps have a window. A future agent in a headless container
can't see a window. So your deliverable here is not a markdown file
that says "`npm start` opens a window" - it's a **driver script** that
launches the app under xvfb, exposes a REPL of commands (click, type,
screenshot), and lets an agent poke the UI by sending lines of text.

The skill's `SKILL.md` then becomes a short manual for that driver.

## What you're building

```
apps/desktop/
  .claude/skills/run-desktop/
    SKILL.md               <- short. "run the driver, here are the commands"
    driver.mjs             <- REPL: stdin commands -> Playwright actions
```

The driver IS the product. Without it, the skill describes a GUI an
agent can never touch.

**Graduation path:** if the driver grows launch helpers the project's
real e2e suite wants to share, move it to `e2e-playwright/driver.mjs`
(or `scripts/drive.mjs`) and update the skill's paths. The skill stays
at `.claude/skills/run-desktop/`; the driver finds a better home.

## Step 1 - get the app to launch AT ALL under xvfb

This is usually the hardest part and produces most of the Gotchas. The
README will say "macOS/Windows only." Ignore that. Install xvfb + the
Chromium shared libs, find the Electron binary, and launch it:

```bash
apt-get install -y xvfb libnss3 libgbm1 libasound2t64 libgtk-3-0 \
  libxss1 libxkbcommon0 libatk-bridge2.0-0 libcups2 libdrm2

# Build the app first. Often the "dev" script is electron-forge which
# does a Vite/webpack build THEN launches. You want just the build:
npm install
npx electron-forge start &   # builds .vite/build/ or dist/
sleep 20 && kill %1          # kill it once built - you'll launch yourself

# Now try the raw launch
xvfb-run -a node -e "
  const { _electron } = require('playwright-core');
  _electron.launch({
    executablePath: './node_modules/electron/dist/electron',
    args: ['--no-sandbox', '.'],
    timeout: 30000,
  }).then(app => {
    console.log('launched, windows:', app.windows().map(w => w.url()));
    return app.close();
  });
"
```

Iterate until it launches. Each missing `.so` -> one more `apt-get`
package -> one more line in Prerequisites. Each launch timeout -> check
the `nodeCliInspect` fuse isn't disabled, check the build output exists.

**`--no-sandbox` is almost always needed in containers.** Electron's
sandbox needs CAP_SYS_ADMIN or user namespaces. Neither by default.

## Step 2 - build the REPL driver

Once you can launch it, turn that throwaway script into a REPL. Start
minimal - you will add commands as you need them. **The REPL is the
right shape** because an agent can run it inside tmux and iterate
without relaunching the (slow) app on every interaction.

```javascript
// .claude/skills/run-<unit>/driver.mjs
// REPL driver for <app>. Run under xvfb on headless Linux.
// Designed for agents: wrap in tmux, send-keys commands, capture-pane output.
import { _electron as electron } from 'playwright-core';
import * as readline from 'node:readline';
import * as fs from 'node:fs';
import * as path from 'node:path';

const APP_DIR = path.resolve(import.meta.dirname, '../../..');
const SHOT_DIR = process.env.SCREENSHOT_DIR || '/tmp/shots';
fs.mkdirSync(SHOT_DIR, { recursive: true });

let app = null;
let page = null;   // the window/page you actually interact with

const electronBin = process.platform === 'darwin'
  ? path.join(APP_DIR, 'node_modules/electron/dist/Electron.app/Contents/MacOS/Electron')
  : path.join(APP_DIR, 'node_modules/electron/dist/electron');

const COMMANDS = {
  async launch() {
    if (app) return console.log('already launched');
    app = await electron.launch({
      executablePath: electronBin,
      args: ['--no-sandbox', APP_DIR],
      env: { ...process.env, DISPLAY: process.env.DISPLAY || ':99' },
      timeout: 30_000,
    });
    // Electron has no clean "loaded" signal - this sleep is a blind guess.
    // Replace with a poll once you know what ready looks like for this app:
    // wait until windows() includes the expected URL, or waitForSelector on firstWindow().
    await new Promise(r => setTimeout(r, 8_000));
    // Find the real UI page. Often NOT firstWindow() - may be a
    // splash screen, or the real content is in a BrowserView overlay.
    page = app.windows().find(w => !w.url().startsWith('devtools://'))
        ?? await app.firstWindow();
    console.log('launched.', app.windows().length, 'windows:');
    for (const w of app.windows()) console.log(' ', w.url());
  },

  async ss(name) {
    if (!page) return console.log('ERROR: launch first');
    const f = path.join(SHOT_DIR, (name || `ss-${Date.now()}`) + '.png');
    await page.screenshot({ path: f });
    console.log('screenshot:', f);
  },

  // Click via evaluate(), NOT locator.click(). If the content lives in a
  // BrowserView layered over the main window, Playwright's coordinate
  // math hits the wrong layer. DOM .click() always works.
  async click(sel) {
    if (!page) return console.log('ERROR: launch first');
    const r = await page.evaluate(s => {
      const el = document.querySelector(s);
      if (!el) return 'NOT_FOUND';
      el.click(); return 'OK';
    }, sel);
    console.log('click', sel, '->', r);
  },

  async 'click-text'(text) {
    if (!page) return console.log('ERROR: launch first');
    const r = await page.evaluate(t => {
      const els = [...document.querySelectorAll('button, a, [role="button"]')];
      const el = els.find(e => e.textContent?.trim() === t)
              ?? els.find(e => e.textContent?.includes(t));
      if (!el) return 'NOT_FOUND';
      el.click(); return 'OK: ' + el.tagName;
    }, text);
    console.log('click-text', JSON.stringify(text), '->', r);
  },

  async type(text)  { if (page) await page.keyboard.type(text, { delay: 30 }); },
  async press(key)  { if (page) await page.keyboard.press(key); },

  async wait(sel) {
    if (!page) return console.log('ERROR: launch first');
    try { await page.waitForSelector(sel, { timeout: 10_000 }); console.log('found:', sel); }
    catch { console.log('TIMEOUT:', sel); }
  },

  async eval(expr) {
    if (!page) return console.log('ERROR: launch first');
    try { console.log(JSON.stringify(await page.evaluate(expr))); }
    catch (e) { console.log('ERROR:', e.message); }
  },

  async text(sel) {
    if (!page) return console.log('ERROR: launch first');
    console.log(await page.evaluate(
      s => (s ? document.querySelector(s) : document.body)?.innerText ?? '(null)',
      sel || null));
  },

  // Introspection: essential for figuring out which window/webContents
  // actually has the UI. Electron apps often spawn several.
  async windows() {
    if (!app) return console.log('ERROR: launch first');
    for (const w of app.windows()) console.log(' ', w.url());
    const wcs = await app.evaluate(({ webContents }) =>
      webContents.getAllWebContents().map(w => ({ id: w.id, type: w.getType(), url: w.getURL() })));
    console.log('webContents:');
    for (const w of wcs) console.log(` [${w.id}] ${w.type}: ${w.url}`);
  },

  async quit() { if (app) await app.close().catch(()=>{}); app = null; page = null; },
  help() { console.log('commands:', Object.keys(COMMANDS).join(', ')); },
};

// Stop Electron from stealing stdin - use the raw fd.
const stdin = fs.createReadStream(null, { fd: fs.openSync('/dev/stdin', 'r') });
const rl = readline.createInterface({ input: stdin, output: process.stdout, prompt: 'driver> ' });

rl.on('line', async line => {
  const [cmd, ...rest] = line.trim().split(/\s+/);
  if (!cmd) return rl.prompt();
  const fn = COMMANDS[cmd];
  if (!fn) { console.log('unknown:', cmd, ' - try: help'); return rl.prompt(); }
  try { await fn(rest.join(' ')); } catch (e) { console.log('ERROR:', e.message); }
  if (cmd === 'quit') { rl.close(); process.exit(0); }
  rl.prompt();
});
rl.on('close', async () => { await COMMANDS.quit(); process.exit(0); });

console.log('<app> driver - "help" for commands, "launch" to start');
rl.prompt();
```

**This is a starting skeleton.** As you try to reach interesting parts
of the app you'll add app-specific commands: navigate to a particular
view, focus a weird input type, bypass an auth gate, whatever. Those
commands encode hard-won knowledge - keep them.

## Step 3 - use it yourself, via tmux

Run the driver the same way the next agent will:

```bash
tmux new-session -d -s app -x 200 -y 50
tmux send-keys -t app 'cd /workspace/apps/desktop && xvfb-run -a node .claude/skills/run-desktop/driver.mjs' Enter
timeout 20 bash -c 'until tmux capture-pane -t app -p | grep -q "driver>"; do sleep 0.2; done'
tmux send-keys -t app 'launch' Enter
timeout 60 bash -c 'until tmux capture-pane -t app -p | grep -q "launched"; do sleep 0.2; done'
tmux send-keys -t app 'ss 01-landing' Enter
timeout 10 bash -c 'until tmux capture-pane -t app -p | grep -q "screenshot:"; do sleep 0.2; done'
tmux send-keys -t app 'windows' Enter    # which page has the real UI?
tmux capture-pane -t app -p
```

Then actually open `/tmp/shots/01-landing.png`. Is it the app? Is it
blank? Is it a login screen? Each of these tells you what to do next.

Keep going - click into the main feature, fill a form, see the result
show up, screenshot it. The driver grows whatever commands you need
(`focus-input`, `goto-settings`, `login-as-test-user`...). When one real
flow works end-to-end, you're done building and ready to write.

## Step 4 - write SKILL.md

Keep it short. The driver is the meat; `SKILL.md` is the manual.
Structure that works:

> ---
> name: run-desktop
> description: Build, run, and drive the <app> Electron desktop app. Use when asked to start the desktop app, take a screenshot of it, build it, or interact with its UI.
> ---
>
> <App> is an Electron desktop app. For agent/automated use, drive it
> via the Playwright REPL at `.claude/skills/run-desktop/driver.mjs`
> under xvfb. Launch is slow (~10s) and the interesting UI lives in a
> BrowserView, not the main window - the driver handles both.
>
> All paths are relative to `apps/desktop/`.
>
> ## Prerequisites
>
> ```bash
> apt-get install -y xvfb libnss3 libgbm1 libasound2t64 libgtk-3-0 \
>   libxss1 libxkbcommon0 libatk-bridge2.0-0 libcups2 libdrm2
> ```
>
> ## Build
>
> ```bash
> npm install
> npx electron-forge start   # builds .vite/build/ - Ctrl-C once built
> # <any patch you had to apply: sed a feature gate, etc.>
> ```
>
> ## Run (agent path)
>
> ```bash
> cd apps/desktop
> xvfb-run -a node .claude/skills/run-desktop/driver.mjs
> ```
>
> Wrap in tmux for interactive use:
>
> ```bash
> tmux new-session -d -s app -x 200 -y 50
> tmux send-keys -t app 'cd apps/desktop && xvfb-run -a node .claude/skills/run-desktop/driver.mjs' Enter
> timeout 20 bash -c 'until tmux capture-pane -t app -p | grep -q "driver>"; do sleep 0.2; done'
> tmux send-keys -t app 'launch' Enter
> timeout 60 bash -c 'until tmux capture-pane -t app -p | grep -q "launched"; do sleep 0.2; done'
> tmux send-keys -t app 'ss landing' Enter
> tmux capture-pane -t app -p
> ```
>
> Screenshots land in `/tmp/shots/` (override: `SCREENSHOT_DIR`).
>
> ### Commands
>
> | command | what it does |
> |---|---|
> | `launch` | launch the app, wait for windows |
> | `ss [name]` | screenshot -> `/tmp/shots/<name>.png` |
> | `click <css-sel>` | click element (via DOM, not coords - see Gotchas) |
> | `click-text <text>` | click button/link containing text |
> | `type <text>` / `press <key>` | keyboard input |
> | `wait <css-sel>` | wait for element, 10s timeout |
> | `eval <js>` | evaluate in the page, print JSON |
> | `text [css-sel]` | print innerText |
> | `windows` | list all windows + webContents (find the real UI) |
> | `quit` | close app, exit |
>
> Plus any app-specific commands you built: `<your-command>` - <what it does>.
>
> ## Run (human path)
>
> ```bash
> npm start   # opens a window; useless headless. Ctrl-C to quit.
> ```
>
> ## Gotchas
>
> - **<the specific weird thing you hit>** - <why> -> <fix/workaround>
> - <etc. - only things you actually hit, not generic advice>
>
> ## Troubleshooting
>
> - **Launch timeout (30s):** build output missing? -> re-run the build
>   step. `nodeCliInspect` fuse disabled? -> Playwright can't attach;
>   don't disable that fuse in dev builds.
> - **"Missing X server":** forgot `xvfb-run`. Headless Linux needs it.
> - **Stale Xvfb locks:** `rm -f /tmp/.X*-lock; pkill Xvfb`
> - <anything else you actually hit>

## Obstacles you will hit (and they go in Gotchas)

These are real patterns from real Electron apps. You'll hit some subset:

- **`firstWindow()` gives you a splash/loading screen,** not the app.
  Wait longer, or find the right page by URL, or wait for a specific
  selector that only appears when the app is actually ready.

- **The real UI is in a BrowserView, not a BrowserWindow.** Playwright
  sees it as a separate "window" with a different URL. The `windows`
  command exists exactly for figuring this out. `getBrowserViews()`
  may also return empty on newer Electron - use
  `webContents.getAllWebContents()` instead.

- **`locator.click()` clicks the wrong thing.** Playwright computes
  click coordinates relative to the main window. If your content is in
  a BrowserView overlay, those coordinates hit the window behind it.
  The driver skeleton uses `page.evaluate(el => el.click())` for this
  reason - DOM click bypasses coordinates entirely.

- **Feature gates block the thing you need to test.** The app checks a
  plan tier, or an env flag, or a feature flag baked into SSR HTML.
  Find where the check happens (grep the built output for the gate
  name) and patch it for your local run - a `sed` on the build output,
  an env var override, or (for SSR-embedded flags) intercept the
  response via CDP `Fetch.enable` and rewrite it in-flight. Document
  exactly what you patched and why.

- **contentEditable inputs** (ProseMirror, Tiptap, Slate) aren't
  `<textarea>`. `fill()` won't work. Focus the element, then use
  `keyboard.type()`. Add a `focus <sel>` command if the app has these.

- **Electron steals stdin.** The `fs.openSync('/dev/stdin', 'r')` +
  `createReadStream` trick in the skeleton protects your REPL's input.

- **Native modules fail to load** (keychain, notifications, etc.).
  Usually non-fatal - the core app runs, those features no-op. Note it
  and move on.

