// Drives a VS Code window with the extension under development loaded.
// Listens on 127.0.0.1:PORT; each request is one command:
//   curl -s localhost:7788 -d '{"cmd":"launch","arg":"/path/to/folder"}'
// The VS Code profile lives under the OS temp dir, as .vscode-test.mjs keeps
// it: a longer path overflows the macOS socket path limit.
import { _electron as electron } from 'playwright-core';
import * as http from 'node:http';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';

const PORT = Number(process.env.PORT || 7788);
const EXT = '/Users/abhi/Documents/entire-vscode';
const CODE = path.join(EXT, '.vscode-test/vscode-darwin-arm64-1.147.0/Visual Studio Code.app/Contents/MacOS/Code');
const SHOTS = process.env.SHOTS;
fs.mkdirSync(SHOTS, { recursive: true });

let app = null;
let page = null;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function profile() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'entire-demo-'));
  fs.mkdirSync(path.join(dir, 'user', 'User'), { recursive: true });
  fs.mkdirSync(path.join(dir, 'ext'), { recursive: true });
  fs.writeFileSync(
    path.join(dir, 'user', 'User', 'settings.json'),
    JSON.stringify({
      'workbench.startupEditor': 'none',
      'window.restoreWindows': 'none',
      'telemetry.telemetryLevel': 'off',
      'workbench.tips.enabled': false,
      'chat.disableAIFeatures': true,
      'workbench.secondarySideBar.defaultVisibility': 'hidden',
      'workbench.colorTheme': 'Default Dark Modern',
      'update.mode': 'none',
      'extensions.ignoreRecommendations': true,
      'git.openRepositoryInParentFolders': 'never',
    }),
  );
  return dir;
}

const commands = {
  async launch(folder) {
    if (app) return 'already launched';
    const dir = profile();
    app = await electron.launch({
      executablePath: CODE,
      args: [
        `--extensionDevelopmentPath=${EXT}`,
        `--user-data-dir=${path.join(dir, 'user')}`,
        `--extensions-dir=${path.join(dir, 'ext')}`,
        '--disable-workspace-trust',
        '--skip-welcome',
        '--skip-release-notes',
        '--new-window',
        folder,
      ],
      timeout: 60_000,
    });
    page = await app.firstWindow();
    await page.waitForSelector('.monaco-workbench', { timeout: 60_000 });
    await app.evaluate(({ BrowserWindow }) => {
      const win = BrowserWindow.getAllWindows()[0];
      win.setBounds({ x: 80, y: 60, width: 1440, height: 900 });
    });
    await sleep(3000);
    return `launched ${page.url()}`;
  },
  async ss(name) {
    const file = path.join(SHOTS, `${name}.png`);
    await page.screenshot({ path: file });
    return file;
  },
  async press(key) {
    await page.keyboard.press(key);
    return 'ok';
  },
  async type(text) {
    await page.keyboard.type(text, { delay: 25 });
    return 'ok';
  },
  /** Runs a command by its title through the Command Palette. */
  async palette(title) {
    await page.keyboard.press('F1');
    await page.waitForSelector('.quick-input-widget:not([style*="display: none"]) input', { timeout: 5000 });
    await page.keyboard.type(title, { delay: 15 });
    await sleep(600);
    await page.keyboard.press('Enter');
    return 'ok';
  },
  async click(selector) {
    await page.click(selector, { timeout: 5000 });
    return 'ok';
  },
  async hover(selector) {
    await page.hover(selector, { timeout: 5000 });
    return 'ok';
  },
  async wait(selector) {
    await page.waitForSelector(selector, { timeout: 20_000 });
    return 'found';
  },
  async sleep(ms) {
    await sleep(Number(ms));
    return 'ok';
  },
  async eval(expr) {
    return JSON.stringify(await page.evaluate(expr));
  },
  /** Text of every frame whose URL matches, for the webview pages. */
  async frames(match) {
    return page
      .frames()
      .map((f) => f.url())
      .filter((u) => !match || u.includes(match))
      .join('\n');
  },
  async frameText(match) {
    const out = [];
    for (const frame of page.frames()) {
      if (match && !frame.url().includes(match)) continue;
      try {
        out.push(`${frame.url().slice(0, 80)}\n${await frame.evaluate(() => document.body?.innerText ?? '')}`);
      } catch (e) {
        out.push(`${frame.url().slice(0, 80)}: ${e.message}`);
      }
    }
    return out.join('\n----\n');
  },
  /** Clicks a link or button in a webview frame by its text. */
  async frameClick(text) {
    for (const frame of page.frames()) {
      const hit = await frame
        .evaluate((t) => {
          const el = [...document.querySelectorAll('a, button')].find((e) => e.textContent.trim() === t);
          if (!el) return false;
          el.click();
          return true;
        }, text)
        .catch(() => false);
      if (hit) return `clicked in ${frame.url().slice(0, 60)}`;
    }
    return 'NOT_FOUND';
  },
  async quit() {
    if (app) await app.close().catch(() => {});
    app = null;
    page = null;
    return 'closed';
  },
};

http
  .createServer((req, res) => {
    let body = '';
    req.on('data', (c) => (body += c));
    req.on('end', async () => {
      try {
        const { cmd, arg } = JSON.parse(body || '{}');
        const fn = commands[cmd];
        if (!fn) throw new Error(`unknown command ${cmd}`);
        if (cmd !== 'launch' && !page) throw new Error('launch first');
        res.end(`${await fn(arg)}\n`);
      } catch (e) {
        res.statusCode = 500;
        res.end(`ERROR: ${e.message}\n`);
      }
    });
  })
  .listen(PORT, '127.0.0.1', () => console.log(`driver listening on ${PORT}`));

