/**
 * Clicks a link or button in a webview frame by its text, with a real
 * mouse event. VS Code's webview host ignores untrusted (synthetic) clicks
 * on links, and the frame then follows the command: link itself.
 */
async frameMouse(text) {
  for (const frame of page.frames()) {
    const target = frame.locator('a, button', { hasText: text }).first();
    if ((await target.count().catch(() => 0)) === 0) continue;
    await target.click({ timeout: 5000 });
    return `clicked in ${frame.url().slice(0, 60)}`;
  }
  return 'NOT_FOUND';
},
